import { InputInputEventDetail, SelectChangeEventDetail, ToggleChangeEventDetail, SearchbarInputEventDetail, InfiniteScrollCustomEvent } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Apply UTC-7 offset for Hermosillo
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormData {
  name: string;
  rewardType: 'discount' | 'free_product' | '';
  requiredPoints: number | '';
  discountValue: number | '';
  freeProductId: number | null;
  isActive: boolean;
  description: string;
}

const REWARD_TYPES: { value: 'discount' | 'free_product'; label: string }[] = [
  { value: 'discount', label: 'Descuento' },
  { value: 'free_product', label: 'Producto Gratis' },
];

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();

  const [items, setItems] = useState<PosRewardCatalogItem[]>([]);
  const [availableProducts, setAvailableProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastColor, setToastColor] = useState<'success' | 'danger' | 'warning'>('success');

  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedItem, setSelectedItem] = useState<PosRewardCatalogItem | null>(null);
  const [formData, setFormData] = useState<FormData>({
    name: '',
    rewardType: '',
    requiredPoints: '',
    discountValue: '',
    freeProductId: null,
    isActive: true,
    description: '',
  });

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  const [searchText, setSearchText] = useState('');
  const [infiniteScrollDisabled, setInfiniteScrollDisabled] = useState(false);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
