    setIsEditing(false);
    setSelectedItem(null);
    setFormData({
      name: '',
      rewardType: '',
      requiredPoints: '',
      discountValue: '',
      freeProductId: null,
      isActive: true,
      description: '',
    });
    setShowModal(true);
  };

  const handleEditClick = (item: PosRewardCatalogItem) => {
    setIsEditing(true);
    setSelectedItem(item);
    setFormData({
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints,
      discountValue: item.discountValue !== null ? item.discountValue : '',
      freeProductId: item.freeProductId,
      isActive: item.isActive,
      description: item.description !== null ? item.description : '',
    });
    setShowModal(true);
  };

  const handleModalDismiss = () => {
    setShowModal(false);
    setSaving(false);
  };

  const validateFormData = () => {
    if (!formData.name.trim()) {
      setError('El nombre es requerido.');
      return false;
    }
    if (!formData.rewardType) {
      setError('El tipo de recompensa es requerido.');
      return false;
    }
    if (typeof formData.requiredPoints !== 'number' || formData.requiredPoints <= 0) {
      setError('Los puntos requeridos deben ser un número positivo.');
      return false;
    }

    if (formData.rewardType === 'discount') {
      if (typeof formData.discountValue !== 'number' || formData.discountValue <= 0) {
        setError('El valor del descuento debe ser un número positivo.');
        return false;
      }
    } else if (formData.rewardType === 'free_product') {
      if (!formData.freeProductId) {
        setError('Debe seleccionar un producto gratis.');
        return false;
      }
    }
    return true;
  };

  const handleSave = async () => {
    if (!validateFormData()) return;

    setSaving(true);
    try {
      const payload = {
        companyId,
        name: formData.name,
        rewardType: formData.rewardType,
        requiredPoints: Number(formData.requiredPoints),
        discountValue: formData.rewardType === 'discount' && typeof formData.discountValue === 'number' ? Number(formData.discountValue) : null,
        freeProductId: formData.rewardType === 'free_product' ? formData.freeProductId : null,
        isActive: formData.isActive,
        description: formData.description.trim() !== '' ? formData.description : null,
