                    type="number"
                    value={formData.requiredPoints}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormData(p => ({ ...p, requiredPoints: parseFloat(e.detail.value!) || '' }))}
                    className={typeof formData.requiredPoints !== 'number' || formData.requiredPoints <= 0 ? 'ion-invalid ion-touched' : ''}
                    errorText={typeof formData.requiredPoints !== 'number' || formData.requiredPoints <= 0 ? 'Debe ser un número positivo.' : ''}
                  />
                </div>

                {formData.rewardType === 'discount' && (
                  <div className="wizard-field-group">
                    <IonInput
                      fill="outline"
                      label="Valor de Descuento *"
                      labelPlacement="floating"
                      type="number"
                      value={formData.discountValue}
                      onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormData(p => ({ ...p, discountValue: parseFloat(e.detail.value!) || '' }))}
                      className={typeof formData.discountValue !== 'number' || formData.discountValue <= 0 ? 'ion-invalid ion-touched' : ''}
                      errorText={typeof formData.discountValue !== 'number' || formData.discountValue <= 0 ? 'Debe ser un número positivo.' : ''}
                    />
                  </div>
                )}

                {formData.rewardType === 'free_product' && (
                  <div className="wizard-field-group">
                    <IonSelect
                      fill="outline"
                      label="Producto Gratis *"
                      labelPlacement="floating"
                      value={formData.freeProductId}
                      onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormData(p => ({ ...p, freeProductId: e.detail.value! }))}
                      className={!formData.freeProductId ? 'ion-invalid ion-touched' : ''}
                      errorText={!formData.freeProductId ? 'Seleccione un producto.' : ''}
                    >
                      <IonSelectOption value={null}>Seleccione un producto</IonSelectOption>
                      {availableProducts.map(product => (
                        <IonSelectOption key={product.productId} value={product.productId}>
                          {product.name}
                        </IonSelectOption>
                      ))}
                    </IonSelect>
                  </div>
                )}

                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Descripción"
                    labelPlacement="floating"
                    value={formData.description}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormData(p => ({ ...p, description: e.detail.value! }))}
                  />
                </div>

                <IonItem lines="none" className="ion-no-padding wizard-field-group">
                  <IonLabel>Activo</IonLabel>
                  <IonToggle
                    slot="end"
                    checked={formData.isActive}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormData(p => ({ ...p, isActive: e.detail.checked }))}
                  />
                </IonItem>
              </div>
            </form>
          </IonContent>
          <IonToolbar>
            <IonButtons slot="end" className="ion-padding-end ion-padding-bottom">
              <IonButton onClick={handleModalDismiss} fill="outline" color="medium">
                Cancelar
              </IonButton>
              <IonButton onClick={handleSave} expand="block" disabled={saving}>
                {saving ? <IonSpinner name="dots" /> : (isEditing ? 'Actualizar' : 'Guardar')}
              </IonButton>
            </IonButtons>
          </IonToolbar>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={itemToDelete ? `¿Está seguro que desea eliminar "${itemToDelete.name}"?` : '¿Está seguro que desea eliminar este elemento?'}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />

        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={toastColor}
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
